pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        vm.assume(from != address(0));
        // Call transfer first time
        (bool success1,) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));
        // If first call succeeded, second call must also succeed and return true
        if (success1) {
            (bool success2, bytes memory ret) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));
            assertTrue(success2 && abi.decode(ret, (bool)), "Second call should succeed and return true");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        // Ensure caddress is an EOA (no code) so calls to transferFrom on it don't revert
        vm.assume(caddress.code.length == 0);
        // Record the balance of the target address before the call
        uint256 balanceBefore = caddress.balance;
        // Call transfer
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));
        // Check that the call succeeded and balance is unchanged
        assertTrue(success && caddress.balance == balanceBefore);
    }
}
